{"implementation":"def solve(case):
    payload = case.get("payload", case) if isinstance(case, dict) else {}
    segments = list(payload.get("segments", []))
    budget = int(payload.get("budget", 0) or 0)

    n = len(segments)
    allocations = [0] * n

    mins = []
    caps = []
    for seg in segments:
        mn = int(seg.get("minimum", 0) or 0)
        cap = int(seg.get("capacity", mn) or 0)
        if cap < 0:
            cap = 0
        if mn < 0:
            mn = 0
        if mn > cap:
            mn = cap
        mins.append(mn)
        caps.append(cap)

    total_min = sum(mins)

    if budget >= total_min:
        allocations = mins[:]
        remaining = min(budget, sum(caps)) - total_min
        order = sorted(
            range(n),
            key=lambda i: (-float(segments[i].get("importance", 0) or 0), i),
        )
        for i in order:
            if remaining <= 0:
                break
            add = min(caps[i] - allocations[i], remaining)
            if add > 0:
                allocations[i] += add
                remaining -= add
    else:
        remaining = max(0, budget)
        order = sorted(
            range(n),
            key=lambda i: (-float(segments[i].get("importance", 0) or 0), i),
        )
        for i in order:
            if remaining <= 0:
                break
            add = min(mins[i], caps[i], remaining)
            if add > 0:
                allocations[i] += add
                remaining -= add

    by_segment = {}
    items = []
    total_score = 0
    for i, seg in enumerate(segments):
        name = str(seg.get("name", i))
        amount = int(allocations[i])
        importance = seg.get("importance", 0) or 0
        by_segment[name] = amount
        items.append({"name": name, "allocation": amount})
        total_score += amount * importance

    return {
        "allocations": by_segment,
        "segments": items,
        "total_allocated": int(sum(allocations)),
        "score": total_score,
    }
"}
